{#- Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/post-split.json
    A post header with the author, the reading figures, the tags and the actions. Axes: layout (center: tags, figures and an author card with share and save over a wide cover; split: beside the cover; outline: facts and related reading beside the cover), mediaSide, author (line, card, bio), cover (wide, square), actions (pair, wide, icons), tone.
    Props (p): id, post, labels, extras, level, layout, mediaSide, author, cover, actions, tone, landmarkLabel. -#}
{%- set v_id = (p.id ?? null) -%}
{%- set v_post = (p.post ?? null) -%}
{%- set v_labels = (p.labels ?? null) -%}
{%- set v_extras = (p.extras ?? null) -%}
{%- set v_level = (p.level ?? 1) -%}
{%- set v_layout = (p.layout ?? 'split') -%}
{%- set v_mediaSide = (p.mediaSide ?? 'end') -%}
{%- set v_author = (p.author ?? 'line') -%}
{%- set v_cover = (p.cover ?? 'wide') -%}
{%- set v_actions = (p.actions ?? 'pair') -%}
{%- set v_tone = (p.tone ?? 'default') -%}
{%- set v_landmarkLabel = (p.landmarkLabel ?? null) -%}
{%- if ui_t(ui_eq(v_layout, 'center')) %}
  {%- set f_1 -%}
    {{ include('blocks/media-frame.html.twig', {'p': {'alt': ui_get(v_post, ['title']), 'ratio': (ui_t(ui_eq(v_layout, 'center')) ? '21/9' : (ui_t(ui_eq(v_cover, 'square')) ? '1/1' : '4/3'))}}, with_context = false) }}
  {%- endset -%}
  {%- set c_2 -%}
    {{ include('blocks/post-tags.html.twig', {'p': {'tags': ui_get(v_extras, ['tags']), 'align': 'center'}}, with_context = false) }}
    {{ include('blocks/post-stats.html.twig', {'p': {'post': v_post, 'extras': v_extras, 'labels': v_labels, 'align': 'center'}}, with_context = false) }}
    {{ include('blocks/post-author.html.twig', {'p': {'post': v_post, 'extras': v_extras, 'labels': v_labels, 'mode': 'card', 'share': true, 'className': ui_cnv(['mx-auto w-full max-w-md'])}}, with_context = false) }}
  {%- endset -%}
  {{ include('blocks/section-frame.html.twig', {'p': {'id': v_id, 'title': ui_get(v_post, ['title']), 'lead': ui_get(v_post, ['excerpt']), 'heading': {'badge': ui_get(v_post, ['category']), 'level': v_level}, 'tone': v_tone, 'media': {'show': true}, 'align': 'center', 'landmarkLabel': v_landmarkLabel, 'aside': f_1}, 'children': c_2}, with_context = false) }}
{%- else %}
  {%- set f_3 -%}
    {{ include('blocks/media-frame.html.twig', {'p': {'alt': ui_get(v_post, ['title']), 'ratio': (ui_t(ui_eq(v_layout, 'center')) ? '21/9' : (ui_t(ui_eq(v_cover, 'square')) ? '1/1' : '4/3'))}}, with_context = false) }}
  {%- endset -%}
  {%- set c_4 -%}
    {%- if ui_t(ui_eq(v_layout, 'outline')) %}
      {{ include('blocks/post-outline.html.twig', {'p': {'post': v_post, 'extras': v_extras, 'labels': v_labels}}, with_context = false) }}
    {%- else %}
      {{ include('blocks/post-author.html.twig', {'p': {'post': v_post, 'extras': v_extras, 'labels': v_labels, 'mode': v_author}}, with_context = false) }}
      {%- if ui_t(not (ui_eq(v_author, 'line'))) %}
        {{ include('blocks/post-stats.html.twig', {'p': {'post': v_post, 'extras': v_extras, 'labels': v_labels}}, with_context = false) }}
      {%- endif %}
      {{ include('blocks/post-tags.html.twig', {'p': {'tags': ui_get(v_extras, ['tags'])}}, with_context = false) }}
    {%- endif %}
    {{ include('blocks/post-actions.html.twig', {'p': {'labels': v_labels, 'mode': v_actions}}, with_context = false) }}
  {%- endset -%}
  {{ include('blocks/section-frame.html.twig', {'p': {'id': v_id, 'title': ui_get(v_post, ['title']), 'lead': ui_get(v_post, ['excerpt']), 'heading': {'badge': ui_get(v_post, ['category']), 'level': v_level}, 'tone': v_tone, 'media': {'show': true, 'side': v_mediaSide}, 'layout': 'split', 'landmarkLabel': v_landmarkLabel, 'aside': f_3}, 'children': c_4}, with_context = false) }}
{%- endif %}
